card_css:
/* Variante 1: Glassmorphism Clássico */
.sl-card {
  background-color: var(--sl-card-bg);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 15px;
  box-shadow: 0 4px 30px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.sl-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.2);
  border-color: rgba(255, 255, 255, 0.4);
}

/* Variante 2: Frosted Glass */
.sl-card {
  background-color: var(--sl-card-bg);
  backdrop-filter: blur(15px) saturate(1.2);
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 10px;
  box-shadow: 0 6px 35px rgba(0, 0, 0, 0.15);
  transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}
.sl-card:hover {
  background-color: rgba(var(--sl-card-bg-rgb), 0.35);
  transform: scale(1.02);
  box-shadow: 0 10px 45px rgba(0, 0, 0, 0.25);
  border-color: rgba(255, 255, 255, 0.5);
}

/* Variante 3: Glass com Borda Destacada */
.sl-card {
  background-color: var(--sl-card-bg);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 20px;
  box-shadow: 0 2px 20px rgba(0, 0, 0, 0.08);
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  border: 1px solid var(--sl-primary); /* Accent color on hover */
  box-shadow: 0 0 15px var(--sl-primary), 0 4px 25px rgba(0, 0, 0, 0.15); /* Soft glow */
  transform: translateY(-3px);
}

/* Variante 4: Glass Minimalista e Suave */
.sl-card {
  background-color: var(--sl-card-bg);
  backdrop-filter: blur(5px);
  border: none; /* No visible border for a cleaner look */
  border-radius: 30px;
  box-shadow: 0 2px 15px rgba(0, 0, 0, 0.05);
  transition: all 0.2s ease-out;
}
.sl-card:hover {
  box-shadow: 0 5px 20px rgba(0, 0, 0, 0.1);
  transform: scale(1.01);
  background-color: rgba(var(--sl-card-bg-rgb), 0.1);
}

/* Variante 5: Glass Profundo e Opaco */
.sl-card {
  background-color: var(--sl-card-bg);
  backdrop-filter: blur(12px) brightness(0.9);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  box-shadow: 0 5px 25px rgba(0, 0, 0, 0.2);
  transition: all 0.3s ease;
}
.sl-card:hover {
  background-color: rgba(var(--sl-card-bg-rgb), 0.45);
  box-shadow: 0 8px 35px rgba(0, 0, 0, 0.3);
  transform: translateZ(5px); /* subtle 3D lift */
  border-color: rgba(255, 255, 255, 0.2);
}

/* Variante Nova 1: Neumorphic Glass */
.sl-card {
  background: var(--sl-card-bg);
  backdrop-filter: blur(8px) saturate(180%);
  -webkit-backdrop-filter: blur(8px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 1rem;
  box-shadow:
    5px 5px 10px rgba(0, 0, 0, 0.1),
    -5px -5px 10px rgba(255, 255, 255, 0.05),
    inset 2px 2px 5px rgba(0, 0, 0, 0.05),
    inset -2px -2px 5px rgba(255, 255, 255, 0.02);
  transition: all 0.3s ease;
}
.sl-card:hover {
  box-shadow:
    7px 7px 14px rgba(0, 0, 0, 0.15),
    -7px -7px 14px rgba(255, 255, 255, 0.07),
    inset 3px 3px 6px rgba(0, 0, 0, 0.07),
    inset -3px -3px 6px rgba(255, 255, 255, 0.03);
  transform: translateY(-2px);
}

/* Variante Nova 2: Art Deco Glass (Geometric & Gilded) */
.sl-card {
  background: var(--sl-card-bg);
  backdrop-filter: blur(7px) saturate(170%);
  -webkit-backdrop-filter: blur(7px) saturate(170%);
  border: none;
  border-radius: 0;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.1) inset,
              0 0 0 2px var(--sl-primary) inset;
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 10px; left: 10px; right: 10px; bottom: 10px;
  border: 1px solid;
  border-image: linear-gradient(45deg, #FFD700 0%, #DAA520 50%, #FFD700 100%) 1;
  opacity: 0.7;
  pointer-events: none;
  z-index: 1;
}
.sl-card:hover {
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.1) inset,
              0 0 0 3px var(--sl-primary) inset;
  transform: scale(1.01);
}

/* Variante Nova 3: Vapor Wave Glass */
.sl-card {
  background: var(--sl-card-bg);
  backdrop-filter: blur(10px) saturate(200%);
  -webkit-backdrop-filter: blur(10px) saturate(200%);
  border: 2px solid;
  border-image: linear-gradient(45deg, #FF69B4, #8A2BE2) 1;
  border-radius: 1.5rem;
  box-shadow: 0 0 15px rgba(138, 43, 226, 0.5),
              0 0 30px rgba(255, 105, 180, 0.3);
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
}
.sl-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255,255,255,0.05),
    rgba(255,255,255,0.05) 1px,
    transparent 1px,
    transparent 3px
  );
  z-index: 1;
  pointer-events: none;
}
.sl-card:hover {
  transform: scale(1.02);
  box-shadow: 0 0 20px rgba(138, 43, 226, 0.7),
              0 0 40px rgba(255, 105, 180, 0.5);
}

/* Variante Nova 4: Organic Blob Glass */
.sl-card {
  background: var(--sl-card-bg);
  backdrop-filter: blur(12px) saturate(190%);
  -webkit-backdrop-filter: blur(12px) saturate(190%);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2),
              inset 0 0 10px rgba(255, 255, 255, 0.05);
  transition: border-radius 0.6s ease-in-out, box-shadow 0.3s ease;
  overflow: hidden;
}
.sl-card:hover {
  border-radius: 70% 30% 30% 70% / 70% 70% 30% 30%;
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.3),
              inset 0 0 15px rgba(255, 255, 255, 0.08);
  transform: translateY(-3px);
}

/* Variante Nova 5: Brutalist Minimal Glass (Dark Mode Focus) */
.sl-card {
  background: var(--sl-card-bg);
  backdrop-filter: blur(4px) brightness(60%) contrast(120%);
  -webkit-backdrop-filter: blur(4px) brightness(60%) contrast(120%);
  border: 2px solid var(--sl-primary);
  border-radius: 0;
  box-shadow: 8px 8px 0px -2px var(--sl-primary);
  color: var(--sl-text-main);
  transition: all 0.2s ease-in-out;
}
.sl-card:hover {
  transform: translate(-4px, -4px);
  box-shadow: 12px 12px 0px -2px var(--sl-primary);
  border-color: var(--sl-primary);
}
.sl-card .btn {
  border-radius: 0;
  box-shadow: none;
  border: 2px solid var(--sl-primary);
  background-color: transparent;
  color: var(--sl-primary);
  font-weight: bold;
}
.sl-card .btn:hover {
  background-color: var(--sl-primary);
  color: var(--sl-bg-body);
}
